import argparse
import csv
import re
import sys
from collections import defaultdict
from datetime import datetime

AY_KALIBI = re.compile(r"^\d{4}-(0[1-9]|1[0-2])$")


def tarih_ay(s):
    s = s.strip()
    for bicim in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y"):
        try:
            return datetime.strptime(s, bicim).strftime("%Y-%m")
        except ValueError:
            continue
    raise ValueError(f"Anlaşılamayan tarih: {s!r}")


def sayi(s):
    s = s.strip().replace(" ", "")
    if "," in s and "." in s:
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", ".")
    return float(s)


def adet_al(s):
    s = s.strip()
    try:
        return int(s)
    except ValueError:
        return sayi(s)


def oku(yol):
    with open(yol, encoding="utf-8-sig", newline="") as f:
        okuyucu = csv.DictReader(f)
        alanlar = {(a or "").strip().lower() for a in (okuyucu.fieldnames or [])}
        eksik = {"tarih", "urun", "adet", "birim_fiyat"} - alanlar
        if eksik:
            sys.exit(f"HATA: Eksik sütun(lar): {', '.join(sorted(eksik))}")
        for i, satir in enumerate(okuyucu, 2):
            if not any((v or "").strip() for v in satir.values()):
                continue
            try:
                ay = tarih_ay(satir["tarih"])
                urun = satir["urun"].strip()
                adet = adet_al(satir["adet"])
                fiyat = sayi(satir["birim_fiyat"])
            except (KeyError, ValueError) as e:
                sys.exit(f"HATA: {yol}, satır {i}: {e}")
            ciro = adet * fiyat
            yield ay, urun, ciro


def ay_yaz(ay, toplam, urunler):
    print(f"\n== {ay} ==")
    print(f"Toplam ciro : {toplam:.2f} TL")
    print("En çok ciro yapan 3 ürün:")
    ilk3 = sorted(urunler.items(), key=lambda x: (-x[1], x[0]))[:3]
    for sira, (urun, ciro) in enumerate(ilk3, 1):
        print(f"  {sira}. {urun:<12} {ciro:.2f} TL")


def main():
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")

    p = argparse.ArgumentParser(description="Aylık satış cirosu raporu")
    p.add_argument("csv_dosyasi", help="satislar.csv")
    p.add_argument("--ay", metavar="YYYY-AA", help="sadece bu ayı göster (örn. 2026-03)")
    args = p.parse_args()

    if args.ay and not AY_KALIBI.match(args.ay):
        p.error(f"--ay biçimi YYYY-AA olmalı: {args.ay!r}")

    aylar = defaultdict(lambda: {"toplam": 0.0, "urunler": defaultdict(float)})
    for ay, urun, ciro in oku(args.csv_dosyasi):
        kayit = aylar[ay]
        kayit["toplam"] += ciro
        kayit["urunler"][urun] += ciro

    if not aylar:
        sys.exit("HATA: Rapora uygun kayıt bulunamadı.")

    hedefler = [args.ay] if args.ay else sorted(aylar)
    if args.ay and args.ay not in aylar:
        sys.exit(f"{args.ay} için kayıt bulunamadı.")

    for ay in hedefler:
        ay_yaz(ay, aylar[ay]["toplam"], aylar[ay]["urunler"])


if __name__ == "__main__":
    main()

